import pathlib,json,hashlib,sys
r=pathlib.Path(__file__).resolve().parents[1];raw=(r/'docs/weather-assets/manifest.json').read_bytes();m=json.loads(raw);specs=[]
for s in m['samples']:
 b=(r/'docs/weather-assets'/s['file']).read_bytes();assert len(b)==s['bytes'] and hashlib.sha256(b).hexdigest()==s['sha256'];specs.append({k:s[k] for k in ['file','bytes','frames','sampleRate','sha256','loop']})
def write(p,s):
 if '--check' in sys.argv:assert p.read_text()==s,str(p)+' stale'
 else:p.write_text(s)
manifest={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
write(r/'docs/weather-catalog.js','// SPDX-License-Identifier: AGPL-3.0-only\n// Generated by tools/generate-weather-catalog.py\nexport const WEATHER_ASSETS='+json.dumps({'manifest':manifest,'samples':specs},separators=(',',':'))+';\n')
a=['new Spec('+','.join([json.dumps(s['file']),str(s['bytes']),str(s['frames']),str(s['sampleRate']),json.dumps(s['sha256']),str(s['loop']).lower()])+')' for s in specs]
write(r/'app/src/main/java/org/sou1/audio/NativeWeatherCatalog.java','// SPDX-License-Identifier: AGPL-3.0-only\n// Generated by tools/generate-weather-catalog.py\npackage org.sou1.audio;\nfinal class NativeWeatherCatalog{private NativeWeatherCatalog(){} static final int MANIFEST_BYTES='+str(manifest['bytes'])+';static final String MANIFEST_HASH='+json.dumps(manifest['sha256'])+';static final Spec[] SAMPLES={'+','.join(a)+'};static final class Spec{final String file,hash;final int bytes,frames,rate;final boolean loop;Spec(String f,int b,int n,int r,String h,boolean l){file=f;bytes=b;frames=n;rate=r;hash=h;loop=l;}}}\n')
